CREATE COLUMN TABLE "TEST_AP"."HMM1" ("DocEntry" INTEGER CS_INT NOT NULL , "LineNum" INTEGER CS_INT NOT NULL , "ViewType" NVARCHAR(1), "ViewName" NVARCHAR(100) NOT NULL , "MenuDesc" NVARCHAR(254), "MenuEnable" NVARCHAR(1), "IAEnable" NVARCHAR(1) DEFAULT 'Y', "SLEnable" NVARCHAR(1), "SLExpose" NVARCHAR(1), PRIMARY KEY ("DocEntry", "LineNum")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "HMM1_UNIQUEVIEW" ON "TEST_AP"."HMM1" ( "ViewName" ASC )